const fmt=(n:number,precise=false)=>{if(n==null)return '—';n=Math.max(0,n);const hours=Math.floor(n/3600000),minutes=Math.floor(n/60000)%60,seconds=Math.floor(n/1000)%60;return `${hours?hours+':':''}${String(minutes).padStart(2,'0')}:${String(seconds).padStart(2,'0')}${precise?'.'+String(Math.floor(n%1000)).padStart(3,'0'):''}`};
const huntHours=(c:any)=>c.lightning?'⚡ 20 minutters lynjakt':c.slot===1?'06.00–15.00':c.slot===2?'15.00–00.00':'06.00–00.00';
const deadline=(c:any)=>new Date(c.end).toLocaleTimeString('nb-NO',{hour:'2-digit',minute:'2-digit',hourCycle:'h23',timeZone:'Europe/Oslo'});
const date=(n:number)=>new Date(n).toLocaleString('nb-NO',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit',timeZone:'Europe/Oslo'});
