useEffect(()=>{refresh();const id=setInterval(refresh,4000);const visible=()=>{if(document.visibilityState==='visible')refresh()};const push=()=>refresh();window.addEventListener('social-updated',push);document.addEventListener('visibilitychange',visible);navigator.serviceWorker?.addEventListener('message',push);return()=>{clearInterval(id);window.removeEventListener('social-updated',push);document.removeEventListener('visibilitychange',visible);navigator.serviceWorker?.removeEventListener('message',push)}},[refresh]);useEffect(()=>{const id=setInterval(()=>setClock(Date.now()+offset.current),100);return()=>clearInterval(id)},[]);
useEffect(()=>{const context=(document as any).modelContext;if(!context?.registerTool)return;const life=new AbortController();Promise.resolve(context.registerTool({name:'read_photo_hunt',description:'Read your current Foto Jakt challenges and season standings. Requires approved membership.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:async(input:any)=>{if(!input||Object.keys(input).length)throw Error('Expected empty object.');const d=await refresh();if(!d||d.user?.status!=='approved')throw Error('Godkjenning kreves.');return {season:d.season,challenges:d.challenges.map((c:any)=>({id:c.id,title:c.title,start:c.start,end:c.end,completed:!!c.own})),leaderboard:d.leaderboard}}},{signal:life.signal})).catch(()=>{});return()=>life.abort()},[refresh]);
async function act(body:any,message='Lagret'){setBusy(true);setErr('');try{const j=await api(body);if(j.resetUser===data?.user?.id&&j.resetChallenge){setCamera(null);await clearAttempt(j.resetUser,j.resetChallenge);setPendingPhotos(rows=>rows.filter(p=>p.challenge!==j.resetChallenge));}await refresh(true);if(message)toast.success(message);return j}catch(e:any){setErr(e.message);toast.error(e.message);return null}finally{setBusy(false)}}
async function logout(){setBusy(true);try{const registration=await navigator.serviceWorker?.getRegistration();const sub=await registration?.pushManager?.getSubscription();await api({action:'logout',endpoint:sub?.endpoint});await sub?.unsubscribe().catch(()=>{});location.href='/'}catch(e:any){setErr(e.message);setBusy(false)}}
