const nav=[['hunt','Dagens',Camera],['discussion','Diskusjon',MessageCircle],['gallery','Bilder',Images],['social','Venner',Users],['profile','Profil',UserRound]] as const;
useEffect(()=>{const changed=()=>toast.info('Jaktordet er byttet på grunn av vanskelighetsgraden. Tidligere bilder og tider er nullstilt. Start jakten på nytt.');window.addEventListener('hunt-word-changed',changed);return()=>window.removeEventListener('hunt-word-changed',changed)},[]);
