if(!data)return <main className="shell">{header}<div className="welcome"><h1>Gjør deg klar til jakt.</h1>{err?<p className="error">{err} <button className="button" onClick={()=>refresh()}>Prøv igjen</button></p>:<LoadingBlock kind={adminPage?'stats':'hunt'} label={adminPage?'Laster administrasjonen':'Laster dagens jakt'}/>}</div></main>;
if(adminPage&&!data.admin)return <main className="shell">{header}<section className="welcome"><div className="entry"><div className="entry-icon"><ShieldCheck size={32}/></div><h2>Andreas sin side</h2><p>Her styrer du jakten.<br/>Skriv inn din firesifrede PIN.</p><form onSubmit={async e=>{e.preventDefault();await act({action:'pin',pin},'Administrasjonen er åpnet');setPin('')}}><div className="flex justify-center my-6"><InputOTP maxLength={4} pattern="[0-9]*" value={pin} onChange={setPin} aria-label="Administratorkode"><InputOTPGroup>{[0,1,2,3].map(i=><InputOTPSlot className="h-14 w-14 text-xl" key={i} index={i}/>)}</InputOTPGroup></InputOTP></div>{err&&<p className="error">{err}</p>}<button className="primary" disabled={busy||pin.length!==4}>Lås opp <LockKeyhole size={18}/></button></form><p className="muted">Kun Andreas bruker denne koden. Deltakere velger sin egen PIN på forsiden.</p></div></section><Toaster/></main>;
if(!data.user)return <Welcome onLogin={()=>refresh(true)} app={app}/>;
if(!adminPage&&data.user.status!=='blocked'&&!app.checked)return <main className="shell">{header}<div className="content"><LoadingBlock kind="hunt" label="Laster appoppsettet"/></div></main>;
