if(data.user.status!=='approved')return <main className="shell">{header}<section className="welcome"><div className="entry"><div className="entry-icon"><Clock/></div><span className="eyebrow">HEI, {data.user.name}!</span><h2>{data.user.status==='blocked'?'Tilgangen er ikke godkjent':'Du står på gjestelisten'}</h2><p>{data.user.status==='blocked'?'Ta kontakt med Andreas hvis du vil bli med.':'Forespørselen er sendt! Andreas må godkjenne deg før jakten kan begynne.'}</p>{data.user.status==='pending'&&<div className="waiting-note"><Clock size={20}/><span>Venter på godkjenning. Spillet åpnes automatisk når du slipper inn. Du kan også komme tilbake senere.</span></div>}{err&&<p className="error">{err}</p>}<button className="button mt-5" disabled={busy} onClick={logout}>Logg ut</button></div></section><Toaster/></main>;
const selectionPending=loadedSelection!==season;const challenges=data.challenges||[],active=challenges.filter((c:any)=>c.start&&c.start<=clock&&c.end>clock),past=challenges.filter((c:any)=>c.start&&c.end<=clock).sort((a:any,b:any)=>b.end-a.end||b.start-a.start),mine=(data.leaderboard||[]).find((m:any)=>m.id===data.user.id),focus=active.find((c:any)=>c.lightning&&!c.own)||active.find((c:any)=>!c.own)||active[0];
